css:
.modul20-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #1b2230;
    background: linear-gradient(170deg, #f4f7fb 0%, #eef3f9 50%, #e9eef6 100%);
    border-radius: 18px;
}

.modul20-container * {
    box-sizing: border-box;
}

.modul20-header {
    text-align: center;
    padding: 30px 22px 26px;
    background: linear-gradient(135deg, #122a4a 0%, #1d4e7e 48%, #2f9c8f 100%);
    color: #f1f8fb;
    border-radius: 16px;
    margin-bottom: 18px;
    box-shadow: 0 16px 36px rgba(18, 42, 74, 0.32);
    position: relative;
    overflow: hidden;
}

.modul20-header::after {
    content: "";
    position: absolute;
    top: -40%;
    right: -10%;
    width: 60%;
    height: 180%;
    background: radial-gradient(circle, rgba(124, 230, 199, 0.30) 0%, rgba(124, 230, 199, 0) 70%);
    pointer-events: none;
}

.modul20-header h1 {
    margin: 12px 0 10px;
    font-size: 2.5rem;
    font-weight: 800;
    letter-spacing: -0.6px;
    color: #ffffff;
    position: relative;
}

.modul20-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.3px;
    font-weight: 700;
    color: #ffe2a6;
    background: rgba(255, 226, 166, 0.14);
    border: 1px solid rgba(255, 226, 166, 0.40);
    padding: 5px 14px;
    border-radius: 999px;
    position: relative;
}

.modul20-subtitle {
    margin: 0 auto;
    max-width: 840px;
    font-size: 1rem;
    line-height: 1.55;
    color: #d4e8ec;
    position: relative;
}

.modul20-brief {
    display: flex;
    gap: 14px;
    margin-bottom: 18px;
}

.modul20-brief-item {
    flex: 1;
    background: #ffffff;
    border-radius: 14px;
    padding: 14px 18px;
    box-shadow: 0 4px 14px rgba(27, 34, 48, 0.08);
    display: flex;
    flex-direction: column;
    gap: 4px;
}

.modul20-brief-budget { border-left: 5px solid #2f9c8f; }
.modul20-brief-decay { border-left: 5px solid #e08a1e; }

.modul20-brief-name {
    font-weight: 800;
    font-size: 1.02rem;
    color: #122a4a;
}

.modul20-brief-budget .modul20-brief-name { color: #1f7a70; }
.modul20-brief-decay .modul20-brief-name { color: #c8780f; }

.modul20-brief-meta {
    font-size: 0.82rem;
    color: #5b6b7d;
    line-height: 1.42;
}

.modul20-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #45566a;
    margin-bottom: 16px;
    padding: 4px;
}

.modul20-period-counter #currentDay,
.modul20-period-counter #maxPeriods {
    font-weight: 800;
    color: #2f9c8f;
}

.modul20-round-name {
    background: rgba(47, 156, 143, 0.14);
    color: #1f7a70;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.modul20-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #b06d12;
    background: rgba(224, 138, 30, 0.14);
    border: 1px solid rgba(224, 138, 30, 0.30);
    padding: 4px 12px;
    border-radius: 999px;
}

.modul20-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.modul20-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    box-shadow: 0 6px 16px rgba(27, 34, 48, 0.08);
    border-top: 4px solid #1d4e7e;
}

.modul20-card-engagement { border-top-color: #2f9c8f; }
.modul20-card-retention { border-top-color: #1d4e7e; }
.modul20-card-completion { border-top-color: #6a5acd; }
.modul20-card-satisfaction { border-top-color: #e08a1e; }

.modul20-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #6b7d8d;
}

.modul20-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #122a4a;
    font-variant-numeric: tabular-nums;
}

.modul20-card-engagement .modul20-value { color: #1f7a70; }
.modul20-card-retention .modul20-value { color: #1d4e7e; }
.modul20-card-completion .modul20-value { color: #5546b8; }
.modul20-card-satisfaction .modul20-value { color: #c8780f; }

.modul20-sublabel {
    font-size: 0.75rem;
    color: #76889a;
    line-height: 1.34;
}

.modul20-status-card.modul20-kpi-danger { border-top-color: #d64545; }
.modul20-status-card.modul20-kpi-danger .modul20-value { color: #d64545; }
.modul20-status-card.modul20-kpi-good { border-top-color: #2f9c8f; }
.modul20-status-card.modul20-kpi-good .modul20-value { color: #1f7a70; }

.modul20-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #ffffff;
    border: 1px solid #dde5ee;
    color: #45566a;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.modul20-budget-bar #budgetDisplay {
    font-size: 1.1rem;
    letter-spacing: 0.3px;
    color: #1f7a70;
    font-weight: 800;
    font-variant-numeric: tabular-nums;
}

.modul20-budget-bar.modul20-budget-over #budgetDisplay { color: #d64545; }
.modul20-budget-bar.modul20-budget-under #budgetDisplay { color: #c8780f; }

.modul20-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #2f9c8f;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(27, 34, 48, 0.07);
}

.modul20-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.modul20-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #122a4a;
    margin-bottom: 6px;
}

.modul20-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #3b4c5e;
}

.modul20-briefing-text strong { color: #1d4e7e; }
.modul20-briefing-text em { color: #c8780f; font-style: italic; }

.modul20-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(27, 34, 48, 0.07);
}

.modul20-controls h3 {
    margin: 0 0 14px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #122a4a;
    border-bottom: 2px solid #e6ecf3;
    padding-bottom: 8px;
}

.modul20-panel-intro {
    font-size: 0.88rem;
    line-height: 1.5;
    color: #5b6b7d;
    background: #f3f8f7;
    border-left: 4px solid #2f9c8f;
    padding: 10px 14px;
    border-radius: 8px;
    margin: 0 0 12px;
}

.modul20-injection {
    font-size: 0.88rem;
    line-height: 1.5;
    color: #8a4b12;
    background: #fdf3e6;
    border: 1px solid #f3d6ad;
    border-left: 4px solid #e08a1e;
    padding: 11px 14px;
    border-radius: 8px;
    margin: 0 0 14px;
    font-weight: 600;
}

.modul20-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #2b3c4e;
    margin: 14px 0 6px;
}

.modul20-container select,
.modul20-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #c6d2dc;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #ffffff;
    color: #1b2230;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.modul20-container select:focus,
.modul20-container input[type="number"]:focus {
    outline: none;
    border-color: #2f9c8f;
    box-shadow: 0 0 0 3px rgba(47, 156, 143, 0.16);
}

.modul20-container select option {
    background-color: #ffffff;
    color: #1b2230;
}

.modul20-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #2f9c8f;
}

.modul20-range-readout,
.modul20-sum-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #45566a;
    margin-top: 4px;
}

.modul20-sum-readout {
    margin-top: 10px;
    padding: 8px 14px;
    background: #f3f8f7;
    border-radius: 9px;
    display: inline-block;
}

.modul20-range-readout span:nth-child(2),
.modul20-sum-readout #sumReadout {
    color: #1f7a70;
    font-weight: 800;
    font-size: 1.05rem;
}

.modul20-sum-readout.modul20-sum-bad {
    background: #fdeaea;
}

.modul20-sum-readout.modul20-sum-bad #sumReadout {
    color: #d64545;
}

.modul20-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.modul20-container .btn-primary {
    background: linear-gradient(135deg, #1d4e7e 0%, #2f9c8f 100%);
    border: none;
    color: #ffffff;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 8px 18px rgba(29, 78, 126, 0.32);
}

.modul20-container .btn-primary:hover {
    filter: brightness(1.07);
}

.modul20-container .btn-outline-secondary {
    margin-left: 10px;
    border: 1px solid #c6d2dc;
    color: #5b6b7d;
    background: transparent;
}

.modul20-coach {
    background: linear-gradient(160deg, #122a4a 0%, #173a5e 100%);
    color: #e1eef0;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 8px 20px rgba(18, 42, 74, 0.26);
}

.modul20-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #ffe2a6;
    margin-bottom: 8px;
}

.modul20-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.modul20-coach-body strong { color: #7ce6c7; }
.modul20-coach-body em { color: #ffe2a6; font-style: italic; }

.modul20-history,
.modul20-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(27, 34, 48, 0.07);
}

.modul20-history h3,
.modul20-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #122a4a;
}

.modul20-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #3b4c5e;
}

.modul20-container table#usfHistoryTable th {
    background: #eef4f3;
    color: #1f7a70;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #d6e3e0;
}

.modul20-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #eef1f3;
    color: #3b4c5e;
}

.modul20-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f7faf9;
}

.modul20-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .modul20-container {
        padding: 14px;
    }
    .modul20-header h1 {
        font-size: 1.8rem;
    }
    .modul20-brief {
        flex-direction: column;
    }
    .modul20-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .modul20-value {
        font-size: 2rem;
    }
    .modul20-clock {
        margin-left: 0;
    }
    .modul20-period-counter {
        font-size: 0.88rem;
    }
    .modul20-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .modul20-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ---- v1.1.0 completion / debrief screen (m20- prefix; Nordlys indigo theme) ---- */
.m20-completion { padding: 8px 4px 4px; }
.m20-cm-head { text-align: center; margin-bottom: 16px; }
.m20-cm-score { font-size: 3.2rem; font-weight: 800; line-height: 1; color: #4b5fd6; }
.m20-cm-score-max { font-size: 1.2rem; font-weight: 600; color: #76889a; }
.m20-cm-grade { font-size: 1.15rem; font-weight: 700; margin-top: 6px; color: #22285a; }
.m20-cm-badge { display: inline-block; margin-left: 6px; padding: 2px 10px; border-radius: 999px; font-size: 0.78rem; font-weight: 700; vertical-align: middle; }
.m20-cm-yes { background: rgba(75,95,214,0.14); color: #4b5fd6; border: 1px solid rgba(75,95,214,0.45); }
.m20-cm-mid { background: rgba(118,136,154,0.15); color: #5f7286; border: 1px solid rgba(118,136,154,0.42); }
.m20-cm-no  { background: rgba(200,64,52,0.12); color: #c84034; border: 1px solid rgba(200,64,52,0.42); }
.m20-cm-metrics { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin: 12px 0 16px; }
.m20-cm-metric { flex: 1 1 100px; min-width: 96px; background: rgba(75,95,214,0.07); border: 1px solid rgba(75,95,214,0.20); border-radius: 10px; padding: 10px 8px; text-align: center; }
.m20-cm-mv { display: block; font-size: 1.2rem; font-weight: 800; color: #4b5fd6; }
.m20-cm-ml { display: block; font-size: 0.68rem; margin-top: 4px; color: #76889a; text-transform: uppercase; letter-spacing: 0.03em; }
.m20-cm-insights-title { font-weight: 700; margin: 8px 0 6px; color: #22285a; }
.m20-cm-insights { margin: 0; padding-left: 20px; }
.m20-cm-insights li { margin-bottom: 8px; line-height: 1.5; font-size: 0.92rem; color: #3a4356; }

