(function() {
    'use strict';

    class ModuleIn20Adapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Module in 20`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Nordlys Learning Lab).
            this.BUDGET = 20;            // hard 20-minute cap
            this.STORYBOARD = 18;        // R2 blocks sum to 18; 2 min reserved for assessment
            this.ASSESS_RESERVE = 2;     // minutes carved out of the 20 for assessment
            this.DECAY_ONSET = 7;        // passive engagement falls off after ~6–7 min
            this.RIVAL_BENCH = 70;       // rivals to beat on completion/retention (%)
            this.SAT_BENCH = 4.0;        // a credible satisfaction target (/5)
            this.CLIENT_VALUE = 9;       // NOK 9M account at stake

            // Starting KPIs (a generic, unoptimised module baseline).
            this.START_ENGAGE = 50;
            this.START_RETAIN = 48;
            this.START_COMPLETE = 62;
            this.START_SAT = 3.4;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    engagement: this.START_ENGAGE,    // %
                    retention: this.START_RETAIN,     // %
                    completion: this.START_COMPLETE,  // %
                    satisfaction: this.START_SAT,     // /5
                    minutesUsed: 0,                   // minutes designed into module
                    // Sticky, run-defining penalty flags (set when an error is committed).
                    contentStuffed: false,            // headline anti-pattern: too much passive content
                    theoryFirst: false,               // opened with abstract theory before relevance
                    weakAssessment: false,            // self-rating only as evidence
                    unscaffolded: false,              // long experiential block, no content scaffold
                    metricsBlind: false,              // ignored designing to the benchmark
                    overBudget: false,                // storyboard broke the 20-minute cap
                    engagementHistory: [this.START_ENGAGE],
                    retentionHistory: [this.START_RETAIN],
                    completionHistory: [this.START_COMPLETE],
                    satisfactionHistory: [this.START_SAT],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults lean toward the classic errors — a blind
                // click-through must NOT auto-win.
                state.decisions = {
                    objective: `broad`,
                    principle: `coverage`,
                    open: `theory`,
                    relevance: 35,
                    contentMin: 13,
                    expMin: 2,
                    retrievalMin: 1,
                    hookMin: 2,
                    sequence: `contentfirst`,
                    assessment: `selfrating`,
                    assessMin: 1,
                    cadence: `uniform`,
                    safeguard: `ignore`,
                    lead: `effort`,
                    rationale: `coverage`,
                    probe: `deny`,
                    conviction: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const ob = document.getElementById(`objectiveInput`);
                const pr = document.getElementById(`principleInput`);
                const op = document.getElementById(`openInput`);
                const re = document.getElementById(`relevanceInput`);
                if (ob) decisions.objective = ob.value;
                if (pr) decisions.principle = pr.value;
                if (op) decisions.open = op.value;
                if (re) decisions.relevance = parseInt(re.value, 10);
                if (!Number.isFinite(decisions.relevance) || decisions.relevance < 0 || decisions.relevance > 100) {
                    warn(`warn_relevance_range`); return false;
                }
            } else if (round === 2) {
                const cm = document.getElementById(`contentMinInput`);
                const em = document.getElementById(`expMinInput`);
                const rm = document.getElementById(`retrievalMinInput`);
                const hm = document.getElementById(`hookMinInput`);
                const sq = document.getElementById(`sequenceInput`);
                if (cm) decisions.contentMin = parseInt(cm.value, 10);
                if (em) decisions.expMin = parseInt(em.value, 10);
                if (rm) decisions.retrievalMin = parseInt(rm.value, 10);
                if (hm) decisions.hookMin = parseInt(hm.value, 10);
                if (sq) decisions.sequence = sq.value;
                const vals = [decisions.contentMin, decisions.expMin, decisions.retrievalMin, decisions.hookMin];
                if (vals.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_minutes_value`); return false;
                }
                const sum = vals.reduce((a, b) => a + b, 0);
                if (sum !== this.STORYBOARD) {
                    warn(`warn_minutes_sum`); return false;
                }
            } else if (round === 3) {
                const asm = document.getElementById(`assessmentInput`);
                const am = document.getElementById(`assessMinInput`);
                const ca = document.getElementById(`cadenceInput`);
                const sf = document.getElementById(`safeguardInput`);
                if (asm) decisions.assessment = asm.value;
                if (am) decisions.assessMin = parseInt(am.value, 10);
                if (ca) decisions.cadence = ca.value;
                if (sf) decisions.safeguard = sf.value;
                if (!Number.isFinite(decisions.assessMin) || decisions.assessMin < 0 || decisions.assessMin > 8) {
                    warn(`warn_assess_range`); return false;
                }
            } else if (round === 4) {
                const le = document.getElementById(`leadInput`);
                const ra = document.getElementById(`rationaleInput`);
                const pb = document.getElementById(`probeInput`);
                const cv = document.getElementById(`convictionInput`);
                if (le) decisions.lead = le.value;
                if (ra) decisions.rationale = ra.value;
                if (pb) decisions.probe = pb.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            this._updateBriefing(state);
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let engDelta = 0, retDelta = 0, compDelta = 0, satDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose: objective, design principle, opening, relevance.
                switch (d.objective) {
                    case `sharp`: retDelta += 5; satDelta += 0.2; break;          // a provable, applicable objective
                    case `broad`: retDelta -= 4; coachKey = `coach_r1_broad`; break; // coverage objective dilutes learning
                    case `awareness`: retDelta -= 2; satDelta -= 0.1; coachKey = `coach_r1_awareness`; break;
                }

                switch (d.principle) {
                    case `experiential`: engDelta += 8; retDelta += 4; satDelta += 0.3; break;
                    case `coverage`: engDelta -= 6; retDelta -= 3; coachKey = `coach_r1_coverage`; break;  // points toward content stuffing
                    case `polish`: engDelta += 2; satDelta += 0.2; retDelta -= 3; coachKey = `coach_r1_polish`; break;
                }

                // The opening — relevance hook vs theory-first (Common Error 2).
                switch (d.open) {
                    case `hook`: engDelta += 9; satDelta += 0.3; if (d.principle === `experiential`) coachKey = `coach_r1_sharp`; break;
                    case `agenda`: engDelta -= 2; coachKey = `coach_r1_agenda`; break;
                    case `theory`: engDelta -= 8; satDelta -= 0.3; ds.theoryFirst = true; coachKey = `coach_r1_theory`; break;
                }

                // Self-relevant framing (andragogy lever).
                if (d.relevance >= 60) { engDelta += 5; retDelta += 3; satDelta += 0.2; }
                else if (d.relevance <= 25) { engDelta -= 4; retDelta -= 2; }

                summaryKey = (d.objective === `sharp` && d.principle === `experiential` && d.open === `hook`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Plan: allocate the 20 minutes (Common Errors 1 & 4).
                const content = d.contentMin;
                const exp = d.expMin;
                const retrieval = d.retrievalMin;
                const hook = d.hookMin;
                ds.minutesUsed = content + exp + retrieval + hook;

                // Passive content beyond the ~7-minute decay onset stops landing and
                // crowds out application — the headline anti-pattern.
                if (content > this.DECAY_ONSET) {
                    ds.contentStuffed = true;
                    const excess = content - this.DECAY_ONSET;
                    engDelta -= 4 + excess * 2.2;       // engagement collapses in the decay zone
                    compDelta -= 3 + excess * 1.8;      // learners drop off
                    retDelta -= excess * 1.2;           // coverage is not retention
                    coachKey = `coach_r2_stuffed`;
                } else {
                    // A lean content scaffold (<= decay onset) is rewarded.
                    engDelta += 4;
                    retDelta += 2;
                }

                // Experiential time drives engagement and transfer — but needs a scaffold.
                engDelta += Math.min(exp, 10) * 1.0;
                retDelta += Math.min(exp, 10) * 0.8;

                // One long experiential block with no content scaffold splits the cohort
                // (Common Error 4: unscaffolded experiential).
                if (d.sequence === `oneblock` && content <= 1) {
                    ds.unscaffolded = true;
                    retDelta -= 7;
                    satDelta -= 0.3;
                    coachKey = `coach_r2_unscaffolded`;
                }

                // Retrieval mid-module both measures and strengthens retention.
                retDelta += Math.min(retrieval, 4) * 1.6;
                // A hook / signposting beat protects attention.
                engDelta += Math.min(hook, 3) * 1.4;

                // Sequencing against the decay curve.
                switch (d.sequence) {
                    case `experientialfirst`: engDelta += 6; retDelta += 4; satDelta += 0.3; break;
                    case `contentfirst`: engDelta -= 4; coachKey = (coachKey === `coach_default`) ? `coach_r2_contentfirst` : coachKey; break;
                    case `oneblock`: engDelta += 2; break;
                }

                // Zero experiential time = a pure lecture; under-teaches and bores.
                if (exp <= 0) { engDelta -= 5; retDelta -= 4; satDelta -= 0.2; }

                if (ds.contentStuffed) summaryKey = `sum_r2_stuffed`;
                else if (ds.unscaffolded) summaryKey = `sum_r2_unscaffolded`;
                else if (content <= this.DECAY_ONSET && exp >= 5 && retrieval >= 2) summaryKey = `sum_r2_good`;
                else summaryKey = `sum_r2_weak`;
            } else if (round === 3) {
                // Decide: assessment method + attention safeguards (Common Error 3).
                // The 18-minute storyboard plus the assessment must fit in 20: a 2-minute
                // reserve is built in, so only assessment minutes beyond that overrun.
                ds.minutesUsed = this.STORYBOARD + d.assessMin;

                switch (d.assessment) {
                    case `scenario`: retDelta += 9; satDelta += 0.3; engDelta += 3; break;     // proves AND strengthens retention
                    case `longquiz`: retDelta += 6; engDelta -= 5; satDelta -= 0.3; coachKey = `coach_r3_longquiz`; break; // strong evidence, starves engagement
                    case `selfrating`: retDelta -= 6; ds.weakAssessment = true; coachKey = `coach_r3_selfrating`; break;   // smiles, not evidence
                }

                // Assessment-minute trade-off: a 6-min quiz starves the experiential blocks.
                if (d.assessMin >= 5) { engDelta -= 4; compDelta -= 3; }
                else if (d.assessMin === 0 && d.assessment !== `selfrating`) { retDelta -= 3; coachKey = (coachKey === `coach_default`) ? `coach_r3_noassess` : coachKey; }

                // Interaction cadence / segment length (Common Error 5: ignore the curve).
                switch (d.cadence) {
                    case `short`: engDelta += 8; compDelta += 6; satDelta += 0.3; break;
                    case `uniform`: engDelta -= 3; compDelta -= 2; coachKey = (coachKey === `coach_default`) ? `coach_r3_uniform` : coachKey; break;
                    case `onelong`: engDelta -= 7; compDelta -= 5; coachKey = `coach_r3_onelong`; break;
                }

                // The mid-round injection: minute-11 drop-off + accessibility.
                switch (d.safeguard) {
                    case `redesign`: engDelta += 6; compDelta += 8; satDelta += 0.3; break;      // re-engagement beat + built-in accessibility
                    case `cutexp`: retDelta -= 5; satDelta -= 0.2; coachKey = `coach_r3_cutexp`; break; // cuts the experiential block to bolt on compliance
                    case `ignore`: compDelta -= 7; satDelta -= 0.3; coachKey = `coach_r3_ignore`; break; // drop-off persists, accessibility fails
                }

                if (d.assessment === `scenario` && d.cadence === `short` && d.safeguard === `redesign`) {
                    coachKey = `coach_r3_strong`;
                }

                if (ds.weakAssessment) summaryKey = `sum_r3_weak_assess`;
                else if (d.assessment === `scenario` && d.cadence === `short` && d.safeguard === `redesign`) summaryKey = `sum_r3_good`;
                else summaryKey = `sum_r3_weak`;
            } else if (round === 4) {
                // Recover: pilot metrics & client defence (Common Error 6).
                switch (d.lead) {
                    case `metrics`: satDelta += 0.3; retDelta += 2; coachKey = `coach_r4_metrics`; break;
                    case `effort`: satDelta -= 0.3; ds.metricsBlind = true; coachKey = `coach_r4_effort`; break;   // coverage-as-defence
                    case `smiles`: satDelta += 0.1; retDelta -= 3; ds.metricsBlind = true; coachKey = `coach_r4_smiles`; break;
                }

                switch (d.rationale) {
                    case `principle`: engDelta += 3; retDelta += 4; satDelta += 0.3; break;
                    case `coverage`: retDelta -= 4; engDelta -= 3; ds.metricsBlind = true; coachKey = `coach_r4_coverage`; break;
                    case `instinct`: retDelta -= 2; coachKey = `coach_r4_instinct`; break;
                }

                switch (d.probe) {
                    case `own`: satDelta += 0.4; retDelta += 2; if (d.rationale === `principle`) coachKey = `coach_r4_own`; break;
                    case `deny`: satDelta -= 0.3; coachKey = `coach_r4_deny`; break;
                    case `blame`: satDelta -= 0.5; engDelta -= 2; coachKey = `coach_r4_blame`; break;
                }

                if (d.conviction >= 60) { satDelta += 0.2; retDelta += 2; }
                else if (d.conviction <= 25) { satDelta -= 0.2; }

                summaryKey = (d.lead === `metrics` && d.rationale === `principle` && d.probe === `own`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // ---- Apply deltas (clamped). ----
            ds.engagement = Math.max(0, Math.min(100, Math.round((ds.engagement + engDelta) * 10) / 10));
            ds.retention = Math.max(0, Math.min(100, Math.round((ds.retention + retDelta) * 10) / 10));
            ds.completion = Math.max(0, Math.min(100, Math.round((ds.completion + compDelta) * 10) / 10));
            ds.satisfaction = Math.max(0, Math.min(5, Math.round((ds.satisfaction + satDelta) * 10) / 10));

            // ---- Over-budget storyboard is a hard, run-defining failure. ----
            if (ds.minutesUsed > this.BUDGET) {
                ds.overBudget = true;
                const over = ds.minutesUsed - this.BUDGET;
                ds.completion = Math.max(0, ds.completion - (4 + over * 2));   // a module that overruns is abandoned
                ds.satisfaction = Math.max(0, Math.round((ds.satisfaction - 0.3) * 10) / 10);
            }

            // ---- STICKY CAPS: each committed error gates the achievable ceilings,
            // so a later good round cannot wash the error out. ----
            // Content stuffing (the headline anti-pattern): engagement and completion capped.
            if (ds.contentStuffed) {
                ds.engagement = Math.min(ds.engagement, 58);
                ds.completion = Math.min(ds.completion, 60);
                ds.retention = Math.min(ds.retention, 62);
            }
            // Theory-first opening: engagement capped (you lost them in the first 90s).
            if (ds.theoryFirst) {
                ds.engagement = Math.min(ds.engagement, 66);
            }
            // Weak assessment: retention is unproven, the client's core ask fails.
            if (ds.weakAssessment) {
                ds.retention = Math.min(ds.retention, 55);
            }
            // Unscaffolded experiential: retention capped (novices floundered).
            if (ds.unscaffolded) {
                ds.retention = Math.min(ds.retention, 60);
            }
            // Over-budget: completion can never look good.
            if (ds.overBudget) {
                ds.completion = Math.min(ds.completion, 58);
            }
            // Metrics-blind defence: satisfaction (the client relationship) capped.
            if (ds.metricsBlind) {
                ds.satisfaction = Math.min(ds.satisfaction, 3.8);
            }

            ds.engagementHistory.push(ds.engagement);
            ds.retentionHistory.push(ds.retention);
            ds.completionHistory.push(ds.completion);
            ds.satisfactionHistory.push(ds.satisfaction);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing(window.mySimulation.state);
            }, 500);

            // v1.1.0: persist composite score + grade to the reporting/grading layer every period.
            // (results_utils.php::express_resolveDomainScore -> performance.overallScore). Scoring UNCHANGED.
            const _score = this._composite(ds);
            ds.performance = { overallScore: _score, grade: this._gradeLetter(_score) };

            return {
                period: state.currentPeriod,
                engagement: ds.engagement,
                engDelta: Math.round(engDelta * 10) / 10,
                retention: ds.retention,
                retDelta: Math.round(retDelta * 10) / 10,
                completion: ds.completion,
                satisfaction: ds.satisfaction,
                minutesUsed: ds.minutesUsed,
                overBudget: ds.overBudget,
                contentStuffed: ds.contentStuffed,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg,
                overallScore: _score,
                score: _score
            };
        }

        _fmtSat(v) {
            // Locale-aware one-decimal score: en "3.4", es "3,4".
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const s = Number(v).toFixed(1);
            return lang === `es` ? s.replace(`.`, `,`) : s;
        }

        _fmtBudget(used) {
            const m = Math.max(0, Math.floor(used));
            const sec = Math.round((used - m) * 60);
            const mm = sec === 60 ? m + 1 : m;
            const ss = sec === 60 ? 0 : sec;
            return `${mm}:${String(ss).padStart(2, `0`)}`;
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

            uiManager.bind(`engagementDisplay`, `domainState.engagement`, (v) => {
                const n = Number(v);
                self._kpiClass(`.modul20-card-engagement`, n >= 70, n < 50);
                return `${Math.round(n)}%`;
            });
            uiManager.bind(`retentionDisplay`, `domainState.retention`, (v) => {
                const n = Number(v);
                self._kpiClass(`.modul20-card-retention`, n >= self.RIVAL_BENCH, n < 50);
                return `${Math.round(n)}%`;
            });
            uiManager.bind(`completionDisplay`, `domainState.completion`, (v) => {
                const n = Number(v);
                self._kpiClass(`.modul20-card-completion`, n >= self.RIVAL_BENCH, n < 55);
                return `${Math.round(n)}%`;
            });
            uiManager.bind(`satisfactionDisplay`, `domainState.satisfaction`, (v) => {
                const n = Number(v);
                self._kpiClass(`.modul20-card-satisfaction`, n >= self.SAT_BENCH, n < 3.2);
                return self._fmtSat(n);
            });

            uiManager.bind(`budgetDisplay`, `domainState.minutesUsed`, (v) => {
                const n = Number(v);
                const bar = document.querySelector(`.modul20-budget-bar`);
                if (bar) {
                    bar.classList.toggle(`modul20-budget-over`, n > self.BUDGET);
                    // Only flag "under" when meaningfully short — 18:00 (storyboard placed,
                    // assessment reserve not yet filled) is the intended interim state.
                    bar.classList.toggle(`modul20-budget-under`, n > 0 && n < self.STORYBOARD);
                }
                return `${self._fmtBudget(n)} / 20:00`;
            });

            // Relevance slider readout.
            const re = document.getElementById(`relevanceInput`);
            const reReadout = document.getElementById(`relevanceReadout`);
            if (re && reReadout) {
                reReadout.textContent = re.value;
                re.addEventListener(`input`, function() { reReadout.textContent = re.value; });
            }

            // Live minute-sum readout for the storyboard fields.
            const minIds = [`contentMinInput`, `expMinInput`, `retrievalMinInput`, `hookMinInput`];
            const sumReadout = document.getElementById(`sumReadout`);
            const updateSum = function() {
                let sum = 0;
                minIds.forEach(function(id) {
                    const el = document.getElementById(id);
                    if (el) { const n = parseInt(el.value, 10); if (Number.isFinite(n)) sum += n; }
                });
                if (sumReadout) {
                    sumReadout.textContent = sum;
                    const box = sumReadout.closest(`.modul20-sum-readout`);
                    if (box) box.classList.toggle(`modul20-sum-bad`, sum !== self.STORYBOARD);
                }
            };
            minIds.forEach(function(id) {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, updateSum);
            });
            updateSum();
        }

        _kpiClass(selector, good, bad) {
            const card = document.querySelector(selector);
            if (!card) return;
            card.classList.toggle(`modul20-kpi-good`, !!good && !bad);
            card.classList.toggle(`modul20-kpi-danger`, !!bad);
        }

        getChartConfig() {
            const t = (window.mySimulation && typeof window.mySimulation.t === 'function') ? window.mySimulation.t.bind(window.mySimulation) : null;
            const L = (k, en) => (t ? t(k) : en);
            return {
                modul20Chart: {
                    type: `line`,
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: L(`chart_ds_engagement`, `Engagement (%)`),
                                data: [],
                                borderColor: `#2f9c8f`,
                                backgroundColor: `rgba(47,156,143,0.12)`,
                                borderWidth: 3,
                                fill: true,
                                tension: 0.25,
                                pointRadius: 5,
                                pointBackgroundColor: `#2f9c8f`,
                                yAxisID: `y`
                            },
                            {
                                label: L(`chart_ds_retention`, `Knowledge retention (%)`),
                                data: [],
                                borderColor: `#1d4e7e`,
                                backgroundColor: `rgba(29,78,126,0.10)`,
                                borderWidth: 2,
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#1d4e7e`,
                                yAxisID: `y`
                            },
                            {
                                label: L(`chart_ds_completion`, `Completion (%)`),
                                data: [],
                                borderColor: `#6a5acd`,
                                backgroundColor: `rgba(106,90,205,0.08)`,
                                borderWidth: 2,
                                borderDash: [4, 3],
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#6a5acd`,
                                yAxisID: `y`
                            },
                            {
                                label: L(`chart_ds_satisfaction`, `Satisfaction (×20)`),
                                data: [],
                                borderColor: `#e08a1e`,
                                backgroundColor: `rgba(224,138,30,0.08)`,
                                borderWidth: 2,
                                borderDash: [6, 4],
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#e08a1e`,
                                yAxisID: `y`
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            legend: { position: `bottom`, labels: { color: `#45566a`, boxWidth: 14 } },
                            title: { display: false }
                        },
                        scales: {
                            y: {
                                beginAtZero: true, max: 100, position: `left`,
                                ticks: { color: `#76889a` }, grid: { color: `rgba(27,42,55,0.06)` },
                                title: { display: true, text: L(`chart_axis_scale`, `0–100`), color: `#76889a` }
                            },
                            x: {
                                ticks: { color: `#76889a` }, grid: { color: `rgba(27,42,55,0.04)` },
                                title: { display: true, text: L(`chart_axis_round`, `Round`), color: `#76889a` }
                            }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.engagementHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            // Satisfaction is /5 — scale ×20 to share the 0–100 axis.
            const satScaled = ds.satisfactionHistory.map((v) => Math.round(v * 20));
            return {
                modul20Chart: {
                    labels: labels,
                    datasets: [
                        { data: ds.engagementHistory.map((v) => Math.round(v)) },
                        { data: ds.retentionHistory.map((v) => Math.round(v)) },
                        { data: ds.completionHistory.map((v) => Math.round(v)) },
                        { data: satScaled }
                    ]
                }
            };
        }

        _composite(ds) {
            const engagement = Math.round(ds.engagement);
            const retention = Math.round(ds.retention);
            const completion = Math.round(ds.completion);
            const satisfaction = Math.round(ds.satisfaction * 10) / 10;
            const satScore = (satisfaction / 5) * 100;
            return Math.round(engagement * 0.25 + retention * 0.28 + completion * 0.27 + satScore * 0.20);
        }

        _verdictKey(ds, composite) {
            const engagement = Math.round(ds.engagement);
            const retention = Math.round(ds.retention);
            const completion = Math.round(ds.completion);
            const satisfaction = Math.round(ds.satisfaction * 10) / 10;
            const engaged = engagement >= 70;
            const retained = retention >= this.RIVAL_BENCH;
            const completed = completion >= this.RIVAL_BENCH;
            const satisfied = satisfaction >= this.SAT_BENCH;
            const inBudget = !ds.overBudget;
            const anyError = ds.contentStuffed || ds.theoryFirst || ds.weakAssessment || ds.unscaffolded || ds.metricsBlind || ds.overBudget;
            if (engaged && retained && completed && satisfied && inBudget && !anyError && composite >= 78) return `verdict_won`;
            if (ds.contentStuffed) return `verdict_stuffed`;
            if (ds.overBudget) return `verdict_overbudget`;
            if (ds.weakAssessment && !retained) return `verdict_noproof`;
            if (ds.unscaffolded) return `verdict_cohort`;
            if (retained && completed && !anyError && composite >= 64) return `verdict_lands`;
            if (composite >= 58) return `verdict_mixed`;
            return `verdict_failed`;
        }

        _gradeLetter(c) {
            if (c >= 85) return `A`;
            if (c >= 75) return `B`;
            if (c >= 62) return `C`;
            if (c >= 50) return `D`;
            if (c >= 35) return `E`;
            return `F`;
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const engagement = Math.round(ds.engagement);
            const retention = Math.round(ds.retention);
            const completion = Math.round(ds.completion);
            const satisfaction = Math.round(ds.satisfaction * 10) / 10;

            // Composite weighted toward the metrics the client benchmarks.
            const composite = this._composite(ds);

            const engaged = engagement >= 70;
            const retained = retention >= this.RIVAL_BENCH;
            const completed = completion >= this.RIVAL_BENCH;
            const satisfied = satisfaction >= this.SAT_BENCH;
            const inBudget = !ds.overBudget;

            const anyError = ds.contentStuffed || ds.theoryFirst || ds.weakAssessment || ds.unscaffolded || ds.metricsBlind || ds.overBudget;

            // Pattern label.
            let pattern = `mixed`;
            if (ds.contentStuffed) pattern = `stuffed`;
            else if (ds.weakAssessment) pattern = `weakassess`;
            else if (ds.unscaffolded) pattern = `unscaffolded`;
            else if (engaged && retained && completed && satisfied) pattern = `designed`;

            // Performance verdict — GATED by the sticky error flags. The headline
            // anti-pattern (content stuffing) and the other run-defining errors
            // cannot reach the top verdict even with otherwise good rounds.
            const T = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? (k) => window.mySimulation.t(k) : (k) => k;
            const verdictKey = this._verdictKey(ds, composite);
            const performance = T(verdictKey);

            const insights = [];
            if (verdictKey === `verdict_won`) insights.push(window.mySimulation.t(`insight_won`));
            else if (ds.contentStuffed) insights.push(window.mySimulation.t(`insight_stuffed`));
            else if (ds.unscaffolded) insights.push(window.mySimulation.t(`insight_unscaffolded`));
            else if (ds.weakAssessment) insights.push(window.mySimulation.t(`insight_weakassess`));
            else insights.push(window.mySimulation.t(`insight_mixed`));

            if (ds.theoryFirst) insights.push(window.mySimulation.t(`insight_theory`));
            if (ds.overBudget) insights.push(window.mySimulation.t(`insight_overbudget`));
            if (ds.metricsBlind) insights.push(window.mySimulation.t(`insight_metricsblind`));
            if (!retained && !ds.weakAssessment) insights.push(window.mySimulation.t(`insight_retention_low`));
            if (engaged && retained && completed && satisfied && !anyError) insights.push(window.mySimulation.t(`insight_balanced`));

            return {
                engagement: engagement,
                retention: retention,
                completion: completion,
                satisfaction: satisfaction,
                engaged: engaged,
                retained: retained,
                completed: completed,
                satisfied: satisfied,
                inBudget: inBudget,
                pattern: pattern,
                composite: composite,
                overallScore: composite,
                verdictKey: verdictKey,
                grade: this._gradeLetter(composite),
                performance: performance,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const T = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? (k) => window.mySimulation.t(k) : (k) => k;
            const s = summary || {};
            const score = (typeof s.overallScore === 'number') ? s.overallScore
                : (typeof s.composite === 'number' ? s.composite : 0);
            const grade = s.grade || '';
            const verdict = s.performance || (s.verdictKey ? T(s.verdictKey) : '');
            const engagement = Math.round(Number(s.engagement || 0)) + '%';
            const retention = Math.round(Number(s.retention || 0)) + '%';
            const completion = Math.round(Number(s.completion || 0)) + '%';
            const satisfaction = this._fmtSat(Number(s.satisfaction || 0));
            const insights = Array.isArray(s.insights) ? s.insights : [];
            const items = insights.map((t) => '<li>' + t + '</li>').join('');
            const won = s.verdictKey === 'verdict_won';
            const badgeCls = won ? 'm20-cm-yes' : (score >= 62 ? 'm20-cm-mid' : 'm20-cm-no');
            const metric = (val, lab) => '<div class="m20-cm-metric"><span class="m20-cm-mv">' + val + '</span><span class="m20-cm-ml">' + lab + '</span></div>';
            const metrics = metric(engagement, T('cm_m_engagement'))
                + metric(retention, T('cm_m_retention'))
                + metric(completion, T('cm_m_completion'))
                + metric(satisfaction, T('cm_m_satisfaction'));
            return ''
                + '<div class="m20-completion">'
                +   '<div class="m20-cm-head">'
                +     '<div class="m20-cm-score">' + score + '<span class="m20-cm-score-max">/100</span></div>'
                +     '<div class="m20-cm-grade">' + verdict + ' <span class="m20-cm-badge ' + badgeCls + '">' + T('cm_grade') + ' ' + grade + '</span></div>'
                +   '</div>'
                +   '<div class="m20-cm-metrics">' + metrics + '</div>'
                +   '<div class="m20-cm-insights-title">' + T('cm_debrief') + '</div>'
                +   '<ul class="m20-cm-insights">' + items + '</ul>'
                + '</div>';
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.overBudget) return window.mySimulation.t(`hint_overbudget`);
            if (ds.contentStuffed) return window.mySimulation.t(`hint_stuffed`);
            if (ds.theoryFirst && ds.engagement < 60) return window.mySimulation.t(`hint_theory`);
            if (ds.weakAssessment && state.currentPeriod >= 3) return window.mySimulation.t(`hint_weakassess`);
            if (ds.unscaffolded) return window.mySimulation.t(`hint_unscaffolded`);
            if (ds.engagement >= 70 && ds.retention >= this.RIVAL_BENCH && ds.completion >= this.RIVAL_BENCH) return window.mySimulation.t(`hint_strong`);
            return null;
        }

        getHistoryTableConfig() {
            const self = this;
            return [
                { key: `period`, label: `Round`, i18nKey: `col_round` },
                { key: `results.summary`, label: `Move`, i18nKey: `col_move` },
                { key: `results.engagement`, label: `Engage`, i18nKey: `col_engage`, formatter: (v) => `${Math.round(v)}%` },
                { key: `results.retention`, label: `Retain`, i18nKey: `col_retain`, formatter: (v) => `${Math.round(v)}%` },
                { key: `results.completion`, label: `Complete`, i18nKey: `col_complete`, formatter: (v) => `${Math.round(v)}%` },
                { key: `results.satisfaction`, label: `Sat`, i18nKey: `col_sat`, formatter: (v) => self._fmtSat(Number(v)) }
            ];
        }

        getPresets() { return null; }

        _updateBriefing(state) {
            const idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            const round = this.ROUNDS[idx];
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;

            const titleEl = document.getElementById(`briefingTitle`);
            if (titleEl) titleEl.textContent = t(round.titleKey);
            const textEl = document.getElementById(`briefingText`);
            if (textEl) textEl.innerHTML = t(round.textKey);
            const nameEl = document.getElementById(`roundNameDisplay`);
            if (nameEl) nameEl.textContent = t(round.nameKey);
            const clockEl = document.getElementById(`clockDisplay`);
            if (clockEl) clockEl.textContent = t(round.clockKey);

            for (let i = 0; i < this.ROUNDS.length; i++) {
                const panel = document.getElementById(this.ROUNDS[i].panelId);
                if (panel) panel.style.display = (i === idx) ? `block` : `none`;
            }
        }

